import pse

pse.initialize()

pedestal = pse.SolverGunPedestal()
pedestal.create(location=(0, 0, -100))

@pedestal.on_element_changed()
def on_pedestal_changed(state):
    if state == 1:
        print("Солвер Ган взят")
    else:
        print("Солвер Ган вернулся на стойку")

while True:
    pse.poll_events()

import pse

pse.initialize()

pedestal = pse.SolverGunPedestal()
pedestal.create(location=(0, 0, -100))

@pedestal.on_element_changed()
def on_pedestal_changed(state):
    if state == 1:
        print("Solver Gun taken")
    else:
        print("Solver Gun returned to the stand")

while True:
    pse.poll_events()
